        orderKg: 10,
        nodes: [
          ProductionMapNode(id: 'start', kind: 'start', title: 'Start'),
          ProductionMapNode(
            id: 'laminatsiya',
            kind: 'apparatus',
            title: _secondLaminationApparatusName,
            apparatusId: apparatus,
          ),
          ProductionMapNode(id: 'end', kind: 'end', title: 'End'),
