    );
    final completed = await MobileApi.instance.adminApparatusQueueActionResult(
      apparatus: apparatus,
      orderId: orderId,
      action: 'complete',
      finishedGoodsKg: 5,
      finishedGoodsMeter: 50,
      bobinaKg: 1,
      laminationPrintLeftoverRolls: 1,
      totalWaste: 1,
      uom: 'm',
    );
    expect(completed.states[orderId], 'completed');
  });
